// ============================================================
// Rule: LNX_Privilege Escalation
// Vendor: Linux
// Objective:
// Detect activity associated with LNX_Privilege Escalation.
// Severity: SEV_040_HIGH
// Category: PRIVILEGE_ESCALATION
// ============================================================
// SANITIZED: Environment-specific values replaced with generic placeholders.
// MITRE ATT&CK:
// Tactic: TA0004 - Privilege Escalation
// Technique: T1548 - Abuse Elevation Control Mechanism
// Technique: T1548.003 - Abuse Elevation Control Mechanism: Sudo and Sudo Caching

// Fonte de dados: eventos coletados de sistemas Linux
dataset = linux_linux_raw  

// Filtro para identificar comandos que utilizam "su -",
// geralmente associados à troca de contexto de usuário ou escalonamento de privilégios
| filter command contains "/bin/su -"  

// Exclusão de contas de serviço conhecidas para reduzir falsos positivos
| filter (username != """<SERVICE_ACCOUNT_1>""")  
| filter (username != """<SERVICE_ACCOUNT_2>""")  
| filter (pwd not contains """/home/<SERVICE_ACCOUNT_1>""") 

// Seleção dos campos mais relevantes para análise
| fields hostname,    // Nome do host de origem
         pwd,         // Diretório de trabalho no momento da execução
         command,     // Comando executado
         username     // Usuário que executou o comando
